import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import Confetti from './Confetti';

const DIFFICULTY_CONFIG = {
  easy: {
    color: '#10B981', // green-500
    glow: '0 0 8px rgba(16, 185, 129, 0.6)',
    points: 5
  },
  medium: {
    color: '#F59E0B', // amber-500
    glow: '0 0 10px rgba(245, 158, 11, 0.7)',
    points: 10
  },
  hard: {
    color: '#EF4444', // red-500
    glow: '0 0 15px rgba(239, 68, 68, 0.8)',
    points: 20
  }
};

// Checkmark SVG Animation
const AnimatedCheckmark = ({ isChecked, onComplete }) => {
  useEffect(() => {
    if (isChecked) {
      const timer = setTimeout(() => {
        if (onComplete) onComplete();
      }, 500); // Wait for animation to complete
      
      return () => clearTimeout(timer);
    }
  }, [isChecked, onComplete]);
  
  return (
    <svg width="24" height="24" viewBox="0 0 24 24" className="text-green-500">
      <motion.path
        d="M5 13l4 4L19 7"
        fill="transparent"
        strokeWidth="2"
        stroke="currentColor"
        strokeLinecap="round"
        strokeLinejoin="round"
        initial={{ pathLength: 0 }}
        animate={{ pathLength: isChecked ? 1 : 0 }}
        transition={{ duration: 0.5, ease: "easeInOut" }}
      />
    </svg>
  );
};

// Task Item Component
const TaskItem = ({ task, onToggle, onDelete, onEdit }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editedTitle, setEditedTitle] = useState(task.title);
  const [showConfetti, setShowConfetti] = useState(false);
  
  const handleCheck = () => {
    if (!task.completed) {
      setShowConfetti(true);
      setTimeout(() => setShowConfetti(false), 2500);
    }
    onToggle(task.id);
  };
  
  const handleEditSubmit = (e) => {
    e.preventDefault();
    if (editedTitle.trim()) {
      onEdit(task.id, { ...task, title: editedTitle });
      setIsEditing(false);
    }
  };
  
  const difficultySettings = DIFFICULTY_CONFIG[task.difficulty];
  
  return (
    <motion.div
      className={`relative p-4 mb-3 rounded-lg bg-gray-800 border border-gray-700 ${
        task.completed ? 'bg-opacity-40' : 'bg-opacity-70'
      }`}
      layout
      initial={{ opacity: 0, y: 20 }}
      animate={{ 
        opacity: 1, 
        y: 0,
        boxShadow: task.completed 
          ? 'none' 
          : difficultySettings.glow
      }}
      exit={{ opacity: 0, x: -100 }}
      transition={{ duration: 0.3 }}
      style={{ 
        borderLeft: `4px solid ${difficultySettings.color}`,
      }}
    >
      {showConfetti && <Confetti />}
      
      <div className="flex items-center">
        <motion.button
          className={`w-6 h-6 mr-3 rounded-full flex items-center justify-center ${
            task.completed ? 'bg-green-500' : 'border-2 border-gray-500 hover:border-white'
          }`}
          whileHover={{ scale: 1.1 }}
          whileTap={{ scale: 0.9 }}
          onClick={handleCheck}
        >
          {task.completed && <AnimatedCheckmark isChecked={task.completed} />}
        </motion.button>
        
        {isEditing ? (
          <form onSubmit={handleEditSubmit} className="flex-grow mr-2">
            <input
              type="text"
              value={editedTitle}
              onChange={(e) => setEditedTitle(e.target.value)}
              className="w-full bg-gray-700 text-white px-3 py-1 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
              autoFocus
              onBlur={handleEditSubmit}
            />
          </form>
        ) : (
          <div className="flex-grow mr-2" onClick={() => setIsEditing(true)}>
            <h3 className={`text-lg font-medium ${task.completed ? 'text-gray-400 line-through' : 'text-white'}`}>
              {task.title}
            </h3>
            <div className="flex items-center mt-1">
              <span className="text-xs text-gray-400 mr-3">
                {task.difficulty.charAt(0).toUpperCase() + task.difficulty.slice(1)}
              </span>
              {task.estimatedTime && (
                <span className="text-xs text-gray-400">
                  {task.estimatedTime} min
                </span>
              )}
            </div>
          </div>
        )}
        
        <motion.button
          className="p-2 text-gray-400 hover:text-white"
          whileHover={{ scale: 1.1 }}
          whileTap={{ scale: 0.9 }}
          onClick={() => onDelete(task.id)}
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <line x1="18" y1="6" x2="6" y2="18"></line>
            <line x1="6" y1="6" x2="18" y2="18"></line>
          </svg>
        </motion.button>
      </div>
      
      {/* Progress bar for tasks with estimated time */}
      {task.progress !== undefined && task.estimatedTime > 0 && (
        <div className="mt-3">
          <div className="flex justify-between text-xs text-gray-400 mb-1">
            <span>Progress</span>
            <span>{Math.round(task.progress)}%</span>
          </div>
          <div className="h-2 bg-gray-700 rounded-full overflow-hidden">
            <motion.div
              className="h-full bg-blue-500"
              initial={{ width: 0 }}
              animate={{ width: `${task.progress}%` }}
              transition={{ duration: 0.5, ease: "easeOut" }}
            />
          </div>
        </div>
      )}
    </motion.div>
  );
};

// New Task Form
const NewTaskForm = ({ onAdd }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [title, setTitle] = useState('');
  const [difficulty, setDifficulty] = useState('medium');
  const [estimatedTime, setEstimatedTime] = useState(25);
  
  const handleSubmit = (e) => {
    e.preventDefault();
    if (title.trim()) {
      onAdd({
        id: Date.now(),
        title: title.trim(),
        difficulty,
        estimatedTime: Number(estimatedTime),
        completed: false,
        progress: 0
      });
      
      setTitle('');
      setDifficulty('medium');
      setEstimatedTime(25);
      setIsExpanded(false);
    }
  };
  
  return (
    <motion.div 
      className="p-4 mb-6 bg-gray-800 rounded-lg shadow-lg bg-opacity-60 backdrop-blur-sm"
      initial={false}
      animate={{ height: isExpanded ? 'auto' : '60px' }}
      transition={{ duration: 0.3 }}
    >
      <form onSubmit={handleSubmit}>
        <div className="flex items-center">
          <motion.input
            type="text"
            placeholder="Add a new task..."
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="flex-grow bg-transparent text-white placeholder-gray-400 focus:outline-none focus:ring-0 border-b border-gray-600 focus:border-blue-500 pb-1"
            onFocus={() => setIsExpanded(true)}
            initial={{ width: '100%' }}
            animate={{ width: isExpanded ? '100%' : '100%' }}
          />
          
          {!isExpanded && (
            <motion.button
              type="button"
              className="ml-2 p-2 rounded-full bg-blue-500 text-white"
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
              onClick={() => setIsExpanded(true)}
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <line x1="12" y1="5" x2="12" y2="19"></line>
                <line x1="5" y1="12" x2="19" y2="12"></line>
              </svg>
            </motion.button>
          )}
        </div>
        
        <AnimatePresence>
          {isExpanded && (
            <motion.div
              className="mt-4 grid grid-cols-1 md:grid-cols-2 gap-4"
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.3 }}
            >
              <div>
                <label className="block text-sm font-medium text-gray-400 mb-1">
                  Difficulty
                </label>
                <div className="flex space-x-2">
                  {Object.entries(DIFFICULTY_CONFIG).map(([level, config]) => (
                    <motion.button
                      key={level}
                      type="button"
                      className={`px-3 py-1 rounded-full text-sm ${
                        difficulty === level
                          ? 'bg-opacity-100 text-white'
                          : 'bg-opacity-30 text-gray-300'
                      }`}
                      style={{ 
                        backgroundColor: difficulty === level ? config.color : 'rgba(75, 85, 99, 0.3)'
                      }}
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      onClick={() => setDifficulty(level)}
                    >
                      {level.charAt(0).toUpperCase() + level.slice(1)}
                    </motion.button>
                  ))}
                </div>
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-400 mb-1">
                  Estimated Time (minutes)
                </label>
                <input
                  type="number"
                  min="5"
                  max="180"
                  step="5"
                  value={estimatedTime}
                  onChange={(e) => setEstimatedTime(e.target.value)}
                  className="w-full bg-gray-700 text-white px-3 py-1 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
              
              <div className="md:col-span-2 flex justify-between">
                <motion.button
                  type="button"
                  className="px-4 py-2 text-gray-400 hover:text-white"
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  onClick={() => setIsExpanded(false)}
                >
                  Cancel
                </motion.button>
                
                <motion.button
                  type="submit"
                  className="px-4 py-2 bg-blue-500 text-white rounded-lg shadow-md"
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                >
                  Add Task
                </motion.button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </form>
    </motion.div>
  );
};

// Summary Stats
const TaskSummary = ({ tasks }) => {
  const totalTasks = tasks.length;
  const completedTasks = tasks.filter(task => task.completed).length;
  const completionRate = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;
  
  const earnedPoints = tasks
    .filter(task => task.completed)
    .reduce((sum, task) => sum + DIFFICULTY_CONFIG[task.difficulty].points, 0);
  
  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
      <motion.div 
        className="bg-gray-800 bg-opacity-60 backdrop-blur-sm p-4 rounded-lg"
        whileHover={{ y: -5, boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.3)' }}
      >
        <h3 className="text-lg font-medium text-gray-300 mb-2">Completion</h3>
        <div className="relative h-2 bg-gray-700 rounded-full overflow-hidden mb-2">
          <motion.div
            className="h-full bg-blue-500"
            initial={{ width: 0 }}
            animate={{ width: `${completionRate}%` }}
            transition={{ duration: 1, ease: "easeOut" }}
          />
        </div>
        <div className="flex justify-between text-sm">
          <span className="text-gray-400">{completedTasks}/{totalTasks} tasks</span>
          <span className="text-gray-400">{Math.round(completionRate)}%</span>
        </div>
      </motion.div>
      
      <motion.div 
        className="bg-gray-800 bg-opacity-60 backdrop-blur-sm p-4 rounded-lg"
        whileHover={{ y: -5, boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.3)' }}
      >
        <h3 className="text-lg font-medium text-gray-300 mb-2">Points Earned</h3>
        <div className="text-3xl font-bold text-blue-400">{earnedPoints}</div>
        <div className="text-sm text-gray-400 mt-1">Study Points</div>
      </motion.div>
      
      <motion.div 
        className="bg-gray-800 bg-opacity-60 backdrop-blur-sm p-4 rounded-lg"
        whileHover={{ y: -5, boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.3)' }}
      >
        <h3 className="text-lg font-medium text-gray-300 mb-2">Difficulty</h3>
        <div className="flex space-x-1">
          {Object.entries(DIFFICULTY_CONFIG).map(([level, config]) => {
            const count = tasks.filter(task => task.difficulty === level).length;
            const width = totalTasks > 0 ? (count / totalTasks) * 100 : 0;
            
            return (
              <motion.div
                key={level}
                className="h-7 rounded-sm"
                style={{ backgroundColor: config.color, width: `${width}%` }}
                initial={{ width: 0 }}
                animate={{ width: `${width}%` }}
                transition={{ duration: 1, ease: "easeOut" }}
              />
            );
          })}
        </div>
        <div className="flex justify-between mt-2 text-xs text-gray-400">
          <span>Easy: {tasks.filter(task => task.difficulty === 'easy').length}</span>
          <span>Medium: {tasks.filter(task => task.difficulty === 'medium').length}</span>
          <span>Hard: {tasks.filter(task => task.difficulty === 'hard').length}</span>
        </div>
      </motion.div>
    </div>
  );
};

// Main Component
const AnimatedTaskManagement = () => {
  // Demo data
  const [tasks, setTasks] = useState([
    {
      id: 1,
      title: 'Complete React assignment',
      difficulty: 'hard',
      estimatedTime: 60,
      completed: false,
      progress: 30
    },
    {
      id: 2,
      title: 'Review notes on JavaScript closures',
      difficulty: 'medium',
      estimatedTime: 30,
      completed: false,
      progress: 0
    },
    {
      id: 3,
      title: 'Read chapter 4 of textbook',
      difficulty: 'easy',
      estimatedTime: 45,
      completed: true,
      progress: 100
    }
  ]);
  
  const [filterMode, setFilterMode] = useState('all');
  
  const handleAddTask = (newTask) => {
    setTasks(prev => [newTask, ...prev]);
  };
  
  const handleToggleTask = (taskId) => {
    setTasks(prev => 
      prev.map(task => 
        task.id === taskId 
          ? { ...task, completed: !task.completed, progress: !task.completed ? 100 : task.progress } 
          : task
      )
    );
  };
  
  const handleDeleteTask = (taskId) => {
    setTasks(prev => prev.filter(task => task.id !== taskId));
  };
  
  const handleEditTask = (taskId, updatedTask) => {
    setTasks(prev => 
      prev.map(task => task.id === taskId ? updatedTask : task)
    );
  };
  
  const filteredTasks = tasks.filter(task => {
    if (filterMode === 'all') return true;
    if (filterMode === 'active') return !task.completed;
    if (filterMode === 'completed') return task.completed;
    return true;
  });
  
  return (
    <div className="max-w-3xl mx-auto">
      <h1 className="text-3xl font-bold text-white mb-6">Tasks</h1>
      
      <TaskSummary tasks={tasks} />
      
      <NewTaskForm onAdd={handleAddTask} />
      
      <div className="flex space-x-2 mb-4">
        {['all', 'active', 'completed'].map((filter) => (
          <motion.button
            key={filter}
            className={`px-4 py-2 rounded-lg font-medium ${
              filterMode === filter
                ? 'bg-blue-500 text-white'
                : 'bg-gray-800 text-gray-300 hover:bg-gray-700'
            }`}
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={() => setFilterMode(filter)}
          >
            {filter.charAt(0).toUpperCase() + filter.slice(1)}
          </motion.button>
        ))}
      </div>
      
      <AnimatePresence>
        {filteredTasks.length === 0 ? (
          <motion.div
            className="text-center py-8 text-gray-400"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            No tasks found.
          </motion.div>
        ) : (
          <motion.div layout>
            {filteredTasks.map(task => (
              <TaskItem
                key={task.id}
                task={task}
                onToggle={handleToggleTask}
                onDelete={handleDeleteTask}
                onEdit={handleEditTask}
              />
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default AnimatedTaskManagement; 