import React from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';
import AnimatedTaskManagement from '../components/AnimatedTaskManagement';

const Tasks = ({ tasks }) => {
  const { theme } = useTheme();
  
  // Simple page transition variant
  const pageVariants = {
    initial: { opacity: 0 },
    animate: { opacity: 1, transition: { duration: 0.5 } },
    exit: { opacity: 0, transition: { duration: 0.3 } }
  };
  
  return (
    <motion.div
      initial="initial"
      animate="animate"
      exit="exit"
      variants={pageVariants}
      className="max-w-5xl mx-auto"
    >
      <div className="mb-6 text-center">
        <h1 className={`text-4xl font-bold ${theme.text.primary}`}>
          Task Management
        </h1>
        <p className={`text-lg mt-2 ${theme.text.secondary}`}>
          Organize your study tasks and track your progress
        </p>
      </div>
      
      <div className={`p-6 rounded-xl ${theme.card} backdrop-blur-lg shadow-lg`}>
        <AnimatedTaskManagement initialTasks={tasks} />
      </div>
    </motion.div>
  );
};

export default Tasks; 